<script setup lang="ts">
import StableLabel from '../../shared/StableLabel.vue';
import OperationsRecovery from '../governance/OperationsRecovery.vue';
import {usageLabels} from '../governance/workbench-types';
import {computed,nextTick,onUnmounted,ref,watch} from 'vue';
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';
import FeedbackTableView from './FeedbackTableView.vue';import {useFeedbackSubmission} from './useFeedbackSubmission';
import type {Feedback,FeedbackOverview} from '../../shared/api/feedback';
const app=useApplication(),actions=app.feedbackActions,route=useRoute(),router=useRouter();
const actor=()=>app.session.current.value?.actor.enterpriseId??null,admin=computed(()=>app.session.current.value?.actor.roles.includes('PLATFORM_ADMIN')??false);
const emptyCounts=()=>({ALL:0,PENDING:0,ACCEPTED:0,REJECTED:0,NEEDS_MORE:0});
const overview=ref<FeedbackOverview>({items:[],nextCursor:null,counts:emptyCounts()}),selected=ref<Feedback['state']|null>(null),reviewing=ref(false),loading=ref(false),error=ref<string|null>(null);
const localDevelopment=import.meta.env.DEV&&import.meta.env.VITE_LOCAL_DEV_LOGIN==='1';
let identityEpoch=0,epoch=0,request:AbortController|null=null,cursors:(string|null)[]=[null];
async function load(cursor:string|null=cursors.at(-1)??null){const who=actor(),turn=++epoch;request?.abort();const controller=new AbortController();request=controller;loading.value=true;error.value=null;try{const value=await app.feedback.summaries(cursor,selected.value,reviewing.value,controller.signal);if(turn===epoch&&actor()===who&&!controller.signal.aborted)overview.value=value;}catch(cause){if(turn===epoch&&actor()===who&&!controller.signal.aborted){overview.value={items:[],nextCursor:null,counts:emptyCounts()};error.value=cause instanceof Error?cause.message:'反馈列表暂不可用。';}}finally{if(turn===epoch)loading.value=false;}}
function first(){cursors=[null];return load(null);}
function filter(state:Feedback['state']|null){selected.value=state;void first();}

function next(){if(!overview.value.nextCursor||loading.value)return;cursors.push(overview.value.nextCursor);void load();}
function previous(){if(cursors.length<2||loading.value)return;cursors.pop();void load();}
const submission=useFeedbackSubmission(app.feedback,actor,app.journals),submitDialog=ref<HTMLDialogElement>(),submitBusy=ref(false),submitMeeting=ref(''),submitCategory=ref('WORDING'),submitComment=ref(''),composing=ref(false);
const submissionLocked=computed(()=>submission.command.snapshot.value!==null),detailDialog=ref<HTMLDialogElement>(),detailVisible=ref(false),detailError=ref<string|null>(null),supplement=ref(''),reviewReason=ref(''),decision=ref('NEEDS_MORE'),usageReason=ref(''),usageBusy=ref(false);
const stateLabels:Record<string,string>={PENDING:'待审核',ACCEPTED:'已通过',REJECTED:'已驳回',NEEDS_MORE:'需要补充'},historyLabels:Record<string,string>={SUPPLEMENT:'补充说明',REVIEW:'审核结论',UNDO_REVIEW:'撤销审核',RESAMPLE:'重新采样'};function localTime(value:string){const date=new Date(value);return Number.isFinite(+date)?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(date):'时间暂不可用';}
const detail=actions.detail,locked=computed(()=>actions.pending.value||actions.busy.value||app.operationsCommands.pending.value||usageBusy.value),canLeave=()=>!actions.pending.value&&!actions.busy.value&&!submissionLocked.value&&!submitBusy.value;
async function usageAction(resample=false){if(locked.value||!detail.value||!usageReason.value.trim())return;usageBusy.value=true;detailError.value=null;try{await app.operationsCommands.submit(`/api/v1/operations/${resample?'voiceprints':'corpus'}/${detail.value.feedback.id}/${resample?'resampling':'withdrawal'}`,{expectedRevisionToken:detail.value.feedback.revisionToken,reason:usageReason.value});usageReason.value='';await actions.reload();await load();}catch(cause){failure(cause);}finally{usageBusy.value=false;}}
function failure(cause:unknown){detailError.value=cause instanceof Error?cause.message:'反馈处理尚未确认，请保留原请求。';}
async function openDetail(id:string){const who=actor(),turn=identityEpoch;if(!who||submissionLocked.value)return;if(actions.pending.value)id=actions.command.snapshot.value?.resource??id;detailError.value=null;detailVisible.value=true;await nextTick();if(actor()!==who||turn!==identityEpoch)return;if(!detailDialog.value?.open)detailDialog.value?.showModal();try{await actions.open(id);if(actor()===who&&turn===identityEpoch&&actions.available.value)await router.replace({query:{...route.query,feedbackId:id}});}catch(cause){failure(cause);}}
function closeDetail(){if(!actions.busy.value){detailDialog.value?.close();detailVisible.value=false;if(!actions.pending.value){supplement.value='';reviewReason.value='';}detailError.value=null;}}
async function run(action:()=>Promise<unknown>){if(composing.value||actions.busy.value)return;detailError.value=null;try{await action();supplement.value='';reviewReason.value='';await load();}catch(cause){failure(cause);}}
async function discard(){try{actions.discardRejected();await actions.reload();detailError.value=null;}catch(cause){failure(cause);}}
async function openSubmit(){const who=actor(),turn=identityEpoch;if(!who||actions.pending.value)return;error.value=null;try{submitMeeting.value=typeof route.query.meetingId==='string'?route.query.meetingId:submitMeeting.value;const restored=submission.open(submitMeeting.value);if(restored){submitMeeting.value=restored.meetingId;submitCategory.value=restored.category;submitComment.value=restored.comment;}await nextTick();if(actor()===who&&turn===identityEpoch)submitDialog.value?.showModal();}catch(cause){error.value=cause instanceof Error?cause.message:'反馈原请求暂不可用。';}}
function closeSubmit(){if(!submitBusy.value){submitDialog.value?.close();submitComment.value='';}}
async function submit(){if(submitBusy.value||composing.value)return;submitBusy.value=true;try{if(!submission.available.value)submission.open(submitMeeting.value);await router.replace({query:{...route.query,meetingId:submitMeeting.value}});await submission.submit({meetingId:submitMeeting.value,category:submitCategory.value,comment:submitComment.value});submitComment.value='';submitDialog.value?.close();await router.replace({query:{...route.query,meetingId:undefined}});await first();}catch(cause){error.value=cause instanceof Error?cause.message:'反馈尚未确认，请保留原请求。';}finally{submitBusy.value=false;}}
function discardSubmission(){try{submission.discardRejected();error.value=null;}catch(cause){error.value=cause instanceof Error?cause.message:'原反馈暂无法清理。';}}

const stopPrivacy=watch(()=>actions.available.value,ready=>{if(!ready){supplement.value='';reviewReason.value='';}},{flush:'sync'});
const stopIdentity=watch(()=>[actor(),route.path] as const,([who])=>{identityEpoch++;epoch++;request?.abort();overview.value={items:[],nextCursor:null,counts:emptyCounts()};error.value=null;detailError.value=null;detailVisible.value=false;detailDialog.value?.close();submitDialog.value?.close();submission.dispose();submitComment.value='';supplement.value='';reviewReason.value='';usageReason.value='';usageBusy.value=false;reviewing.value=Boolean(who&&route.path==='/operations/feedback');selected.value=null;cursors=[null];if(who)void first();},{immediate:true,flush:'sync'});
const stopPending=watch(()=>actions.pending.value,pending=>{if(!pending)return;const body=actions.original.value;if(body){supplement.value=typeof body.text==='string'?body.text:'';reviewReason.value=typeof body.reason==='string'?body.reason:'';decision.value=typeof body.decision==='string'?body.decision:'NEEDS_MORE';}const id=actions.command.snapshot.value?.resource;if(id&&!detailVisible.value)void openDetail(id);},{immediate:true,flush:'post'});
const stopQuery=watch(()=>[route.query.feedbackId,route.query.meetingId],async([id,meeting])=>{if(typeof id==='string'&&!detailVisible.value&&!actions.pending.value)await openDetail(id);else if(typeof meeting==='string'&&!id&&!submitDialog.value?.open&&!actions.pending.value)await openSubmit();},{immediate:true});
onBeforeRouteLeave(()=>canLeave());onBeforeRouteUpdate((to,from)=>to.query.feedbackId===from.query.feedbackId&&to.query.meetingId===from.query.meetingId||canLeave());
onUnmounted(()=>{epoch++;request?.abort();stopPending();stopPrivacy();stopIdentity();stopQuery();submission.dispose();});
</script>
<template><div class="layout"><div class="main">
 <main class="content">
 <div v-if="actions.pending.value&&actions.command.snapshot.value" class="page-actions mb16"><button class="btn" @click="openDetail(actions.command.snapshot.value.resource)">恢复原反馈处理</button></div>
  <FeedbackTableView :reviewing="reviewing" :items="overview.items" :counts="overview.counts" :selected="selected" :loading="loading" :error="error??app.feedbackScopeError.value" @select="filter" @open="openDetail"/>
  <div v-if="overview.nextCursor||cursors.length>1" class="pager"><button :disabled="loading||cursors.length<2" @click="previous">上一页反馈</button><button :disabled="loading||!overview.nextCursor" @click="next">下一页反馈</button></div>
  <button v-if="error" class="btn" @click="first">重新读取反馈</button>
  <div v-if="localDevelopment" class="demo-note">当前运行于本地受控环境。反馈、审核与采用状态来自实际接口；本地授权与模型服务用于流程验证。</div>
 </main>
 <dialog ref="detailDialog" class="mask feedback-dialog-root" aria-label="反馈详情" @cancel.prevent="closeDetail"><div class="modal lg"><header class="modal-h"><h3 class="m-t">反馈详情</h3><button class="m-x" :disabled="actions.busy.value" aria-label="关闭反馈详情" @click="closeDetail"><Icon name="x" :size="18"/></button></header><div class="modal-b"><OperationsRecovery/>
  <p v-if="detailError" class="banner error" role="alert">{{detailError}}</p><p v-if="actions.busy.value" role="status">正在核实当前反馈…</p>
  <template v-if="detail&&actions.available.value"><dl><dt>来源会议</dt><dd class="mono">{{detail.feedback.meetingId}}</dd><template v-if="detail.submission"><dt>原始值</dt><dd class="feedback-copy">{{detail.submission.originalValue}}</dd><dt>建议值</dt><dd class="feedback-copy">{{detail.submission.suggestedValue}}</dd><dt>补充说明</dt><dd class="feedback-copy">{{detail.submission.note||'—'}}</dd></template><template v-else><dt>原始反馈</dt><dd class="feedback-copy">{{detail.feedback.comment}}</dd></template><dt>当前状态</dt><dd>{{stateLabels[detail.feedback.state]}}</dd><template v-if="detail.usage"><dt>当前使用状态</dt><dd>{{usageLabels[detail.usage.usageState]}}{{detail.usage.usageVersion?' · '+detail.usage.usageVersion:''}}</dd><dt v-if="detail.usage.withdrawalReason">撤回原因</dt><dd v-if="detail.usage.withdrawalReason">{{detail.usage.withdrawalReason}}</dd></template><dt>审核意见</dt><dd>{{detail.reviewReason??'等待平台管理员审核'}}</dd></dl>
   <ol aria-label="反馈处理历史"><li v-for="item in detail.history" :key="item.id"><span>{{localTime(item.createdAt)}} · {{historyLabels[item.action]}} · {{item.actorId}}</span><p class="feedback-copy">{{item.text||'撤销审核，恢复待审核'}}</p></li></ol>
   <template v-if="!reviewing&&detail.usage?.usageState!=='WITHDRAWN'&&detail.feedback.state==='NEEDS_MORE'"><div class="field"><label for="feedback-supplement">补充说明</label><textarea id="feedback-supplement" v-model="supplement" class="input" rows="3" maxlength="4096" :readonly="locked" @compositionstart="composing=true" @compositionend="composing=false"></textarea></div><button class="btn primary" :disabled="locked||composing||!supplement.trim()" @click="run(()=>actions.supplement(supplement))">提交补充</button></template>
   <section v-if="!reviewing&&(detail.usage?.canWithdraw||detail.feedback.category==='VOICEPRINT'&&['NEEDS_MORE','REJECTED'].includes(detail.feedback.state))" class="field"><label for="feedback-usage-reason">{{detail.feedback.category==='VOICEPRINT'?'重新采样说明':'撤回原因'}}</label><textarea id="feedback-usage-reason" v-model="usageReason" class="input" rows="2" maxlength="2048" :disabled="locked"/><p class="small muted">{{detail.feedback.category==='VOICEPRINT'?'将从来源会议当前版本的原说话人片段重新采样，核实本人授权，并形成新的待审修订。':'撤回后停止新的语料使用，保留原审核记录与已有会议内容。'}}</p><button class="btn" :disabled="locked||!usageReason.trim()" @click="usageAction(detail.feedback.category==='VOICEPRINT')">{{detail.feedback.category==='VOICEPRINT'?'重新采样并提交审核':'撤回本人反馈'}}</button></section>
   <template v-if="admin&&reviewing"><div class="banner info">审核反馈不会授予来源会议的访问权限；审核通过只记录当前处理结论。</div><div class="field"><label for="feedback-review-decision">审核结论</label><select id="feedback-review-decision" v-model="decision" class="select" :disabled="locked"><option value="ACCEPTED">通过</option><option value="REJECTED">驳回</option><option value="NEEDS_MORE">需要补充</option></select></div><div class="field"><label for="feedback-review-reason">审核意见</label><textarea id="feedback-review-reason" v-model="reviewReason" class="input" rows="3" maxlength="2048" :readonly="locked" @compositionstart="composing=true" @compositionend="composing=false"></textarea></div><button v-if="detail.feedback.state==='PENDING'" class="btn primary" :disabled="locked||composing||!reviewReason.trim()" @click="run(()=>actions.review(decision,reviewReason))">提交审核</button><button v-else class="btn" :disabled="locked||composing" @click="run(actions.undo)">撤销审核</button></template>
  </template><p v-if="actions.pending.value" class="small muted" role="status">原反馈处理请求已保留，当前内容只读。</p>
 </div><footer class="modal-f"><button v-if="actions.pending.value&&['CONFLICT','REJECTED'].includes(actions.command.state.value)" class="btn" :disabled="actions.busy.value" @click="discard">放弃已拒绝的原请求</button><button class="btn" :disabled="actions.busy.value" @click="closeDetail">关闭</button><button v-if="actions.pending.value" class="btn primary" :disabled="actions.busy.value||!actions.available.value||!['PREPARED','UNCERTAIN','ACKNOWLEDGED'].includes(actions.command.state.value)" @click="run(actions.retry)"><StableLabel :labels="['重试原反馈处理','重新核实已受理反馈']">{{actions.command.state.value==='ACKNOWLEDGED'?'重新核实已受理反馈':'重试原反馈处理'}}</StableLabel></button></footer></div></dialog>
 <dialog ref="submitDialog" class="mask feedback-dialog-root" aria-label="提交语料反馈" @cancel.prevent="closeSubmit"><div class="modal"><header class="modal-h"><h3 class="m-t">提交语料反馈</h3><button class="m-x" :disabled="submitBusy" aria-label="关闭提交反馈" @click="closeSubmit"><Icon name="x" :size="18"/></button></header><div class="modal-b"><p v-if="error" class="banner error" role="alert">{{error}}</p><div class="field"><label for="feedback-source-meeting">来源会议编号</label><input id="feedback-source-meeting" v-model="submitMeeting" class="input" :readonly="submitBusy||submissionLocked"/></div><div class="field"><label for="feedback-category">反馈类型</label><select id="feedback-category" v-model="submitCategory" class="select" :disabled="submitBusy||submissionLocked"><option value="WORDING">文字</option><option value="LABEL">标签</option><option value="ACTION_OWNER">行动负责人</option></select></div><div class="field"><label for="feedback-comment">反馈内容</label><textarea id="feedback-comment" v-model="submitComment" rows="4" class="input" maxlength="4096" :readonly="submitBusy||submissionLocked" @compositionstart="composing=true" @compositionend="composing=false"></textarea></div></div><footer class="modal-f"><button class="btn" :disabled="submitBusy" @click="closeSubmit">取消</button><button v-if="['CONFLICT','REJECTED'].includes(submission.command.state.value)" class="btn" @click="discardSubmission">放弃已拒绝的原反馈</button><button class="btn primary" :disabled="submitBusy||composing||!submitComment.trim()" @click="submit"><StableLabel :labels="['提交','重试原反馈']">{{submissionLocked?'重试原反馈':'提交'}}</StableLabel></button></footer></div></dialog>

</div></div></template>
<style scoped>.feedback-dialog-root{inset:0;border:0;padding:24px;margin:0;width:100vw;height:100dvh;max-width:none;max-height:none;color:var(--text)}.feedback-dialog-root:not([open]){display:none}.feedback-dialog-root::backdrop{background:transparent}.feedback-dialog-root .input{width:100%}.feedback-copy{white-space:pre-wrap;overflow-wrap:anywhere}.m-t{margin:0}dt{color:var(--muted)}dd{margin:4px 0 12px}</style>
